const MATH_SPANS = /(\$\$[\s\S]*?\$\$|\$(?:\\.|[^$])*?\$|\\\((?:\\.|[^)])*?\\\)|\\\[[\s\S]*?\\\])/g;
const MATH_REPLACEMENTS = [
  [/\bcat=1, dog=2, and horse=3\b/g, "$\\text{cat}=1,\\;\\text{dog}=2,\\;\\text{horse}=3$"],
  [/\bD = \{\(x_i,y_i\)\} from i=1 to N\b/g, "$D=\\{(x_i,y_i)\\}_{i=1}^{N}$"],
  [/\bw-hat=\(Phi\^T Phi\)\^\(-1\)Phi\^T y\b/g, "$\\hat w=(\\Phi^\\top\\Phi)^{-1}\\Phi^\\top y$"],
  [/\bFor x=\{0,1,2\} and y=\{1,2,2\}\b/g, "For $x=\\{0,1,2\\}$ and $y=\\{1,2,2\\}$"],
  [/\bH_M=\{f:f\(x\)=sum_\{j=0\}\^\{M-1\} w_j phi_j\(x\)\}/g, "$\\mathcal H_M=\\{f:f(x)=\\sum_{j=0}^{M-1}w_j\\phi_j(x)\\}$"],
  [/\bphi_0\(x\)=1 and phi_1\(x\)=x\b/g, "$\\phi_0(x)=1$ and $\\phi_1(x)=x$"],
  [/\bx in R with phi\(x\)=\(1,x,x\^2\)/g, "$x\\in\\mathbb R$ with $\\phi(x)=(1,x,x^2)$"],
  [/\bWrite the prediction for phi\(x\)=\(1,x,x\^2\) and weights \(w_0\),\(w_1\),\(w_2\)\b/g, "Write the prediction for $\\phi(x)=(1,x,x^2)$ and weights $(w_0,w_1,w_2)$"],
  [/\bThe three forms are phi_j\(x\)=x\^j, exp\(-\(x-m_j\)\^2\/\(2s\^2\)\), and sigma\(\(x-m_j\)\/s\) with sigma\(b\)=1\/\(1\+e\^{-b}\)\)\./g, "The three forms are $\\phi_j(x)=x^j$, $\\exp\\left(-\\frac{(x-m_j)^2}{2s^2}\\right)$, and $\\sigma\\left(\\frac{x-m_j}{s}\\right)$ with $\\sigma(b)=\\frac{1}{1+e^{-b}}$."],
  [/\bnormal equation Phi\^T Phi w=Phi\^T y\b/g, "normal equation $\\Phi^\\top\\Phi w=\\Phi^\\top y$"],
  [/\bExpanding R\(w\)=1\/\(2N\)\|\|Phi w-y\|\|\^2 gives gradient \(1\/N\)Phi\^T\(Phi w-y\)\. Setting it to zero yields Phi\^T Phi w=Phi\^T y\./g, "Expanding $R(w)=\\frac{1}{2N}\\lVert\\Phi w-y\\rVert^2$ gives gradient $\\frac{1}{N}\\Phi^\\top(\\Phi w-y)$. Setting it to zero yields $\\Phi^\\top\\Phi w=\\Phi^\\top y$."],
  [/\bWhat geometric statement is encoded by Phi\^T\(Phi w-hat-y\)=0\?/g, "What geometric statement is encoded by $\\Phi^\\top(\\Phi\\hat w-y)=0$?"],
  [/\bThe slide minimizes \|\|Phi w-y\|\|\^2, sets the gradient to zero, derives Phi\^T\(Phi w-hat-y\)=0, and states w-hat=\(Phi\^T Phi\)\^\(-1\)Phi\^T y when Phi\^T Phi is invertible\./g, "The slide minimizes $\\lVert\\Phi w-y\\rVert^2$, sets the gradient to zero, derives $\\Phi^\\top(\\Phi\\hat w-y)=0$, and states $\\hat w=(\\Phi^\\top\\Phi)^{-1}\\Phi^\\top y$ when $\\Phi^\\top\\Phi$ is invertible."],
  [/\bTheir difference can lie in the null space of Phi, so Phi\(w_1-w_2\)=0\./g, "Their difference can lie in the null space of $\\Phi$, so $\\Phi(w_1-w_2)=0$."],
  [/\bg\(z\)_k=exp\(z_k\)\/sum_j exp\(z_j\), and L\(z,k\)=-log g\(z\)_k=log\(sum_j exp\(z_j\)\)-z_k\./g, "$g(z)_k=\\frac{e^{z_k}}{\\sum_j e^{z_j}}$ and $L(z,k)=-\\log g(z)_k=\\log\\left(\\sum_j e^{z_j}\\right)-z_k$."],
  [/\by_i=f\*\(x_i\)\b/g, "$y_i=f^*(x_i)$"],
  [/\by_i~p\*\(·\|x_i\)/g, "$y_i\\sim p^*(\\cdot\\mid x_i)$"],
  [/\by_i=f\*\(x_i\)\+epsilon_i\b/g, "$y_i=f^*(x_i)+\\epsilon_i$"],
  [/\bH=\{f:f\(x\)=w_0\+w_1x\}/g, "$\\mathcal H=\\{f:f(x)=w_0+w_1x\\}$"],
  [/\bf-hat/g, "$\\hat f$"],
  [/\bw-hat/g, "$\\hat w$"],
  [/\bf0\b/g, "$f_0$"],
  [/\bPhi\^T/g, "$\\Phi^\\top$"],
  [/\bPhi\^†/g, "$\\Phi^\\dagger$"],
  [/\bR-pop\b/g, "$R_{\\mathrm{pop}}$"],
  [/\bR-emp\b/g, "$\\widehat R$"],
  [/\by-bar\b/g, "$\\bar y$"],
  [/\bx-bar\b/g, "$\\bar x$"],
  [/\bphi_j\b/g, "$\\phi_j$"],
  [/\bphi\(x\)/g, "$\\phi(x)$"],
  [/\bsigma\(b\)/g, "$\\sigma(b)$"],
  [/\bp_true\b/g, "$p_{\\mathrm{true}}$"],
];

const RAW_MATH_TOKEN_PATTERNS = [
  /\\(?:[a-zA-Z]+|[,;:!])/g,
  /\b(?:[xyzwuvprhqke]|Phi|Sigma|Delta|[RKAHXWVSQPCDL])_[A-Za-z0-9]+\b/g,
  /\b[A-Za-z]+(?:\^\{[^}]+\}|\^[A-Za-z0-9†+()-]+)/g,
  /\b(?:f|x|y|z|u|v|w)\s*\*/g,
  /\b(?:argmax|argmin|exp|log|sin|cos|sigmoid|ReLU|softmax)(?=\s*(?:\(|_|\^|[0-9]))/g,
  /\b[A-Za-z][A-Za-z0-9_]*\([^)]*\)/g,
  /\b(?:O|o)\([A-Za-z0-9_+*^ -]+\)/g,
  /\bd[A-Za-z]+\s*\/\s*d[A-Za-z]+\b/g,
  /\b\d+(?:\.\d+)?\s*[+*/-]\s*\d+(?:\.\d+)?\b/g,
  /\b(?:lambda|gamma|epsilon|sigma|mu|alpha|beta|theta|phi|Phi|Sigma|Delta)\b\s*(?:=|[0-9_+*/^-])/gi,
];

function wrapRawMath(text) {
  const formatTokens = segment => {
    const protectedMath = [];
    const protect = match => {
      const key = `⟦${protectedMath.length}⟧`;
      protectedMath.push(`$${match}$`);
      return key;
    };
    let result = segment.replace(/\b([A-Za-z][A-Za-z0-9_]*(?:\^\{[^}]+\}|\^[A-Za-z0-9†+()-]+|\*)?)\s*(=|<=|>=|<|>|∈|⊂|≈|≠)\s*([A-Za-z0-9][A-Za-z0-9_]*(?:\^\{[^}]+\}|\^[A-Za-z0-9†+()-]+|\*)?)/g, protect);
    for (const pattern of RAW_MATH_TOKEN_PATTERNS) {
      result = result.replace(pattern, protect);
    }
    for (let index = protectedMath.length - 1; index >= 0; index -= 1) result = result.replace(`⟦${index}⟧`, protectedMath[index]);
    return result;
  };
  const formatPlainSegment = segment => {
    let replaced = segment;
    for (const [pattern, replacement] of MATH_REPLACEMENTS) replaced = replaced.replace(pattern, replacement);
    return replaced.split(MATH_SPANS).map((part, index) => index % 2 ? part : formatTokens(part)).join("");
  };
  return text.split(MATH_SPANS).map((part, index) => index % 2 ? part : formatPlainSegment(part)).join("");
}

function formatAuthoredText(value) {
  if (typeof value !== "string") return value;
  return wrapRawMath(value);
}

function formatQuestion(question) {
  return Object.fromEntries(Object.entries(question).map(([key, value]) => [key, typeof value === "string" ? formatAuthoredText(value) : value]));
}

function q(type, prompt, answer, hint) {
  return { type, prompt, answer, hint };
}

function note(title, kind, whatYouSee, whyItMatters, intuition, technicalDetail, pitfall, connection, questions, textbookPages = []) {
  return {
    title,
    kind,
    whatYouSee,
    whyItMatters,
    intuition,
    technicalDetail,
    pitfall,
    connection,
    questions,
    textbookRefs: textbookPages.map(page => ({ sourceId: "DSA5105/Textbook.pdf", page, sourceType: "textbook", role: "optional depth" }))
  };
}

